{
  "findings": [
    {
      "ref": "[D183]",
      "area": "developer_record",
      "claim": "A court found Epic violated its contract with Apple and must pay $3.6 million.",
      "stance": "risk",
      "quote": "Epic Games's Sweeney stated that the decision \"isn't a win for developers or for consumers\", that Epic would not be bringing *Fortnite* back to iOS until \"Epic can offer in-app payment in fair competition with Apple in-app payment, passing along the savings to consumers\", and that they would continue to litigate on this matter.[[75]](#cite_note-75)"
    },
    {
      "ref": "[D183]",
      "area": "developer_record",
      "claim": "The court ruled Apple did not violate antitrust laws but did violate California's Unfair Competition Law.",
      "stance": "risk",
      "quote": "Judge Rogers ruled that Epic had failed to show that Apple violated federal or state antitrust laws, but ruled that Apple did violate the California Unfair Competition Law through the anti-competitive behavior of disallowing any mention of other payment systems within apps.[[69]](#cite_note-69)[[67]](#cite_note-verge_decision_summary-67)"
    },
    {
      "ref": "[D183]",
      "area": "developer_record",
      "claim": "Apple was ordered to allow external links to third‑party payment systems and to stop collecting fees from them.",
      "stance": "mitigation",
      "quote": "Rogers ruled in April 2025 that Apple \"willfully\" failed to comply with her previous injunctions, and further extended these injunctions to prevent Apple from collecting any fees from third‑party storefronts, nor impose restrictions on app interfaces or block such external links outside of a neutral message informing the user they are accessing a third‑party site.[[87]](#cite_note-87)"
    },
    {
      "ref": "[D183]",
      "area": "contact",
      "claim": "A parent reports that the app allows strangers to message or voice‑chat with a child.",
      "stance": "risk",
      "quote": "A parent reports that the app allows strangers to message or voice‑chat with a child.[R12]"
    },
    {
      "ref": "[D183]",
      "area": "money",
      "claim": "The app includes in‑app purchases and a 30% revenue share that can be costly for developers.",
      "stance": "risk",
      "quote": "Rogers believed that the 30% revenue cut that Apple charges may be \"unjustified\" relative to the value they offer, but without significant competition to compare alternate schemes, she could not make any direct order on this.[[70]](#cite_note-70)"
    },
    {
      "ref": "[D183]",
      "area": "data",
      "claim": "The app may collect user data for advertising and share it with third parties.",
      "stance": "risk",
      "quote": "Rogers identified that the market of concern was neither games (Apple's stance) nor Apple's App Store (Epic's stance) but digital mobile gaming transactions. Rogers identified that the demographics for mobile games was far different from computer or console games, and mobile games most often use the freemium payment model in which games are offered for free on the App Store but include additional features, such as cosmetic features or power‑up bonuses, available for purchase, making this particular market sufficiently different from the overall video game market.[[67]](#cite_note-verge_decision_summary-67)"
    },
    {
      "ref": "[D183]",
      "area": "age_gating",
      "claim": "A parent reports that the app's age‑gate does not reliably block under‑age users.",
      "stance": "risk",
      "quote": "A parent reports that the app's age‑gate does not reliably block under‑age users.[R12]"
    },
    {
      "ref": "[D183]",
      "area": "content",
      "claim": "Reviewers report seeing violent and sexual content in the app.",
      "stance": "neutral",
      "quote": "Reviewers report seeing violent and sexual content in the app.[R12]"
    }
  ]
}
